CREATE OR REPLACE FUNCTION public.admin_grant_baseball_trial(p_admin uuid, p_member uuid, p_team text, p_part text)
 RETURNS baseball_gear_trials
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t text;
  pt text;
  sl text;
  prev jsonb;
  r baseball_gear_trials;
BEGIN
  IF COALESCE(auth.jwt() ->> 'email', '') <> 'ji.kim@egnis.kr' THEN RAISE EXCEPTION 'NOT_ADMIN'; END IF;
  t := COALESCE(p_team, (ARRAY['lg','doosan','kia','samsung','ssg','lotte','hanwha','nc','kt','kiwoom'])[1 + floor(random() * 10)::int]);
  IF t NOT IN ('lg','doosan','kia','samsung','ssg','lotte','hanwha','nc','kt','kiwoom') THEN RAISE EXCEPTION 'BAD_TEAM'; END IF;
  pt := COALESCE(p_part, (SELECT part FROM baseball_parts ORDER BY random() LIMIT 1));
  SELECT slot INTO sl FROM baseball_parts WHERE part = pt;
  IF sl IS NULL THEN RAISE EXCEPTION 'BAD_PART'; END IF;

  INSERT INTO baseball_equip (member_id) VALUES (p_member) ON CONFLICT (member_id) DO NOTHING;
  SELECT slots -> sl INTO prev FROM baseball_equip WHERE member_id = p_member FOR UPDATE;

  INSERT INTO baseball_gear_trials (member_id, team, part, prev_item, granted_by, expires_at)
  VALUES (p_member, t, pt, prev, p_admin,
          (((now() AT TIME ZONE 'Asia/Seoul')::date + 1)::timestamp AT TIME ZONE 'Asia/Seoul'))
  RETURNING * INTO r;

  UPDATE baseball_equip
     SET slots = slots || jsonb_build_object(sl, jsonb_build_object('part', pt, 'team', t)),
         cap     = CASE WHEN sl = 'head' THEN t ELSE cap END,
         uniform = CASE WHEN sl = 'top' THEN t ELSE uniform END,
         bat     = CASE WHEN sl = 'hand' THEN (CASE WHEN pt = 'bat' THEN t END) ELSE bat END,
         updated_at = now()
   WHERE member_id = p_member;
  RETURN r;
END
$function$

CREATE OR REPLACE FUNCTION public.admin_race_gift(p_admin uuid, p_member uuid, p_part text, p_team text, p_days integer, p_message text)
 RETURNS race_gifts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r race_gifts;
  slot_val jsonb;
BEGIN
  IF COALESCE(auth.jwt() ->> 'email', '') <> 'ji.kim@egnis.kr' THEN RAISE EXCEPTION 'NOT_ADMIN'; END IF;
  INSERT INTO race_gifts (member_id, part, team, expires_at, given_by, message)
  VALUES (p_member, p_part, NULLIF(p_team, ''),
          CASE WHEN COALESCE(p_days, 0) <= 0 THEN NULL
               ELSE (((now() AT TIME ZONE 'Asia/Seoul')::date + 1)::timestamp AT TIME ZONE 'Asia/Seoul') END,
          p_admin, NULLIF(btrim(COALESCE(p_message, '')), ''))
  RETURNING * INTO r;
  INSERT INTO race_garage (member_id) VALUES (p_member) ON CONFLICT (member_id) DO NOTHING;
  IF r.part IN ('sport', 'super') THEN
    UPDATE race_garage SET equipped = (equipped - 'bodyTeam') || jsonb_build_object('body', r.part)
        || CASE WHEN r.team IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('bodyTeam', r.team) END,
      updated_at = now()
    WHERE member_id = p_member;
  ELSE
    slot_val := CASE WHEN r.team IS NULL THEN to_jsonb('own'::text) ELSE to_jsonb(r.team) END;
    UPDATE race_garage SET equipped = equipped || jsonb_build_object(r.part, slot_val), updated_at = now()
    WHERE member_id = p_member;
  END IF;
  RETURN r;
END
$function$

CREATE OR REPLACE FUNCTION public.admin_race_interior_gift(p_admin uuid, p_member uuid, p_slot text, p_v text, p_team text)
 RETURNS race_garage
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  k text := p_slot || ':' || p_v || ':' || COALESCE(p_team, 'base');
  g race_garage;
BEGIN
  IF COALESCE(auth.jwt() ->> 'email', '') <> 'ji.kim@egnis.kr' THEN RAISE EXCEPTION 'NOT_ADMIN'; END IF;
  IF race_interior_kind(p_slot, p_v) IS NULL OR race_interior_kind(p_slot, p_v) = 'free' THEN RAISE EXCEPTION 'UNKNOWN_ITEM %', k; END IF;
  IF NOT race_interior_team_ok(COALESCE(p_team, 'base')) THEN RAISE EXCEPTION 'UNKNOWN_TEAM %', p_team; END IF;
  INSERT INTO race_garage (member_id) VALUES (p_member) ON CONFLICT (member_id) DO NOTHING;
  SELECT * INTO g FROM race_garage WHERE member_id = p_member FOR UPDATE;
  IF k = ANY (g.interior_owned) THEN RAISE EXCEPTION 'ALREADY_OWNED'; END IF;
  UPDATE race_garage SET
    interior_owned = array_append(interior_owned, k),
    interior_gifts = array_append(interior_gifts, k),
    updated_at = now()
  WHERE member_id = p_member RETURNING * INTO g;
  RETURN g;
END
$function$

CREATE OR REPLACE FUNCTION public.admin_send_baseball_box(p_sender uuid, p_recipient uuid, p_team text, p_part text, p_message text)
 RETURNS baseball_gift_boxes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r baseball_gift_boxes;
BEGIN
  IF COALESCE(auth.jwt() ->> 'email', '') <> 'ji.kim@egnis.kr' THEN RAISE EXCEPTION 'NOT_ADMIN'; END IF;
  IF p_team IS NOT NULL AND p_team NOT IN ('lg','doosan','kia','samsung','ssg','lotte','hanwha','nc','kt','kiwoom') THEN RAISE EXCEPTION 'BAD_TEAM'; END IF;
  IF p_part IS NOT NULL AND NOT EXISTS (SELECT 1 FROM baseball_parts WHERE part = p_part) THEN RAISE EXCEPTION 'BAD_PART'; END IF;
  INSERT INTO baseball_gift_boxes (kind, sender_id, recipient_id, cost, message, preset_team, preset_part)
  VALUES ('admin', p_sender, p_recipient, 0, NULLIF(btrim(COALESCE(p_message, '')), ''), p_team, p_part)
  RETURNING * INTO r;
  RETURN r;
END
$function$

CREATE OR REPLACE FUNCTION public.baseball_reward_progress(p_member uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  m_start date := (date_trunc('month', now() AT TIME ZONE 'Asia/Seoul') - interval '1 month')::date;
  m_end date := date_trunc('month', now() AT TIME ZONE 'Asia/Seoul')::date;
  hr int;
  offd int;
  titles int;
  mine int;
  top int;
BEGIN
  SELECT COALESCE(sum(homeruns), 0) INTO hr FROM baseball_plays WHERE member_id = p_member AND finished;
  SELECT count(*) INTO offd FROM playground_state WHERE member_id = p_member AND side = 'off';
  SELECT count(*) INTO titles FROM baseball_tournaments WHERE champion_id = p_member AND status = 'done';
  SELECT COALESCE(sum(homeruns), 0) INTO mine FROM baseball_plays
   WHERE member_id = p_member AND finished AND play_date >= m_start AND play_date < m_end;
  SELECT COALESCE(max(s), 0) INTO top FROM (
    SELECT sum(homeruns) AS s FROM baseball_plays
     WHERE finished AND play_date >= m_start AND play_date < m_end
     GROUP BY member_id
  ) x;
  RETURN jsonb_build_object(
    'homeruns', hr, 'off_days', offd, 'titles', titles,
    'last_month', to_char(m_start, 'YYYY-MM'), 'last_month_hr', mine, 'last_month_top', top,
    'last_month_leader', mine > 0 AND mine = top
  );
END
$function$

CREATE OR REPLACE FUNCTION public.claim_baseball_reward(p_member uuid, p_part text, p_team text)
 RETURNS baseball_gear
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  pr jsonb;
  ok boolean;
  r baseball_gear;
BEGIN
  IF p_team IS NULL OR p_team NOT IN ('lg','doosan','kia','samsung','ssg','lotte','hanwha','nc','kt','kiwoom') THEN RAISE EXCEPTION 'BAD_TEAM'; END IF;
  IF p_part NOT IN ('firework', 'confetti', 'ring', 'goldglove') THEN RAISE EXCEPTION 'BAD_PART'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('baseball_reward:' || p_member::text));
  IF EXISTS (SELECT 1 FROM baseball_gear WHERE member_id = p_member AND part = p_part) THEN RAISE EXCEPTION 'ALREADY_CLAIMED'; END IF;
  pr := baseball_reward_progress(p_member);
  ok := CASE p_part
    WHEN 'firework' THEN (pr ->> 'homeruns')::int >= 10
    WHEN 'confetti' THEN (pr ->> 'off_days')::int >= 5
    WHEN 'ring' THEN (pr ->> 'titles')::int >= 1
    WHEN 'goldglove' THEN (pr ->> 'last_month_leader')::boolean
    ELSE false
  END;
  IF NOT ok THEN RAISE EXCEPTION 'NOT_YET'; END IF;
  INSERT INTO baseball_gear (member_id, team, part) VALUES (p_member, p_team, p_part) RETURNING * INTO r;
  RETURN r;
END
$function$

CREATE OR REPLACE FUNCTION public.ensure_day()
 RETURNS TABLE(date date, sender_id uuid, receiver_id uuid, message text, msg_status text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_date         date := (now() AT TIME ZONE 'Asia/Seoul')::date;
  v_row          day_state%ROWTYPE;
  v_member_count int;
  v_sender       uuid;
  v_receiver     uuid;
BEGIN
  SELECT count(*) INTO v_member_count FROM members m WHERE m.hired_at IS NULL OR m.hired_at <= v_date;

  BEGIN
    INSERT INTO day_state (date) VALUES (v_date);
  EXCEPTION WHEN unique_violation THEN
    NULL;
  END;

  -- day_state.date 앞에 반드시 테이블명을 붙인다: 이 함수는 RETURNS TABLE(date date, ...)로
  -- "date"라는 이름의 OUT 파라미터를 갖고 있어서, 별칭 없이 쓰면 plpgsql이 컬럼과 변수 중
  -- 무엇인지 모호하다며 에러를 낸다 (column reference "date" is ambiguous).
  SELECT * INTO v_row FROM day_state WHERE day_state.date = v_date FOR UPDATE;

  -- 이미 배정됐더라도 아직 입사 전인 사람이 끼어 있고 메시지가 없으면 다시 뽑는다.
  IF v_row.sender_id IS NOT NULL AND v_row.message IS NULL AND EXISTS (
    SELECT 1 FROM members m
    WHERE m.id IN (v_row.sender_id, v_row.receiver_id) AND m.hired_at > v_date
  ) THEN
    v_row.sender_id := NULL;
  END IF;

  IF v_row.sender_id IS NOT NULL OR v_member_count < 2 THEN
    RETURN QUERY SELECT v_row.date, v_row.sender_id, v_row.receiver_id, v_row.message, v_row.msg_status;
    RETURN;
  END IF;

  SELECT m.id INTO v_sender
  FROM members m
  LEFT JOIN (
    SELECT d.sender_id, max(d.date) AS last_date
    FROM day_state d
    WHERE d.sender_id IS NOT NULL
    GROUP BY d.sender_id
  ) s ON s.sender_id = m.id
  WHERE m.hired_at IS NULL OR m.hired_at <= v_date
  ORDER BY s.last_date ASC NULLS FIRST, random()
  LIMIT 1;

  SELECT m.id INTO v_receiver
  FROM members m
  WHERE m.id <> v_sender
    AND (m.hired_at IS NULL OR m.hired_at <= v_date)
    AND NOT EXISTS (
      SELECT 1 FROM day_state d
      WHERE d.sender_id = v_sender AND d.receiver_id = m.id
        AND d.date >= v_date - 14 AND d.date < v_date
    )
  ORDER BY random()
  LIMIT 1;

  IF v_receiver IS NULL THEN
    SELECT m.id INTO v_receiver FROM members m
    WHERE m.id <> v_sender AND (m.hired_at IS NULL OR m.hired_at <= v_date)
    ORDER BY random() LIMIT 1;
  END IF;

  UPDATE day_state SET sender_id = v_sender, receiver_id = v_receiver WHERE day_state.date = v_date;

  RETURN QUERY SELECT v_date, v_sender, v_receiver, v_row.message, v_row.msg_status;
END;
$function$

CREATE OR REPLACE FUNCTION public.equip_baseball_slot(p_member uuid, p_slot text, p_part text, p_team text)
 RETURNS baseball_equip
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r baseball_equip;
  t text;
BEGIN
  IF p_slot NOT IN ('head', 'face', 'top', 'hand', 'acc', 'effect') THEN RAISE EXCEPTION 'BAD_SLOT'; END IF;
  t := CASE WHEN p_part IS NULL THEN NULL ELSE p_team END;
  IF p_part IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM baseball_parts WHERE part = p_part AND slot = p_slot) THEN RAISE EXCEPTION 'BAD_PART'; END IF;
    IF NOT EXISTS (
      SELECT 1 FROM baseball_gear WHERE member_id = p_member AND team = p_team AND part = p_part
    ) AND NOT EXISTS (
      SELECT 1 FROM baseball_gear_trials WHERE member_id = p_member AND team = p_team AND part = p_part AND expires_at > now()
    ) THEN RAISE EXCEPTION 'NOT_OWNED'; END IF;
  END IF;
  INSERT INTO baseball_equip (member_id) VALUES (p_member) ON CONFLICT (member_id) DO NOTHING;
  UPDATE baseball_equip
     SET slots = CASE WHEN p_part IS NULL THEN slots - p_slot
                      ELSE slots || jsonb_build_object(p_slot, jsonb_build_object('part', p_part, 'team', p_team)) END,
         cap     = CASE WHEN p_slot = 'head' THEN t ELSE cap END,
         uniform = CASE WHEN p_slot = 'top' THEN t ELSE uniform END,
         bat     = CASE WHEN p_slot = 'hand' THEN (CASE WHEN p_part = 'bat' THEN t END) ELSE bat END,
         updated_at = now()
   WHERE member_id = p_member
  RETURNING * INTO r;
  RETURN r;
END
$function$

CREATE OR REPLACE FUNCTION public.fort_draw_special(p_member uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM members WHERE id = p_member) THEN RAISE EXCEPTION 'UNKNOWN_MEMBER'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('fort_specials'));
  SELECT special INTO s FROM fort_specials WHERE member_id = p_member;
  IF s IS NOT NULL THEN RETURN s; END IF;
  SELECT k INTO s
  FROM unnest(ARRAY['rain', 'homing', 'bolt', 'quake', 'freeze', 'swap', 'vortex']) AS k
  WHERE k NOT IN (SELECT special FROM fort_specials)
  ORDER BY random() LIMIT 1;
  IF s IS NULL THEN RAISE EXCEPTION 'NO_SPECIAL_LEFT'; END IF;
  INSERT INTO fort_specials (special, member_id) VALUES (s, p_member);
  RETURN s;
END
$function$

CREATE OR REPLACE FUNCTION public.fort_record(p_member uuid, p_fid text, p_result text, p_humans integer, p_mode text)
 RETURNS fort_profile
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  g fort_profile;
BEGIN
  IF p_result NOT IN ('win', 'lose', 'draw') THEN RAISE EXCEPTION 'BAD_RESULT %', p_result; END IF;
  INSERT INTO fort_profile (member_id) VALUES (p_member) ON CONFLICT (member_id) DO NOTHING;
  IF p_humans >= 2 THEN
    INSERT INTO fort_games (member_id, fid, result, humans, mode) VALUES (p_member, p_fid, p_result, p_humans, p_mode)
    ON CONFLICT (member_id, fid) DO NOTHING;
    IF FOUND THEN
      UPDATE fort_profile SET
        games = games + 1,
        wins = wins + CASE WHEN p_result = 'win' THEN 1 ELSE 0 END,
        losses = losses + CASE WHEN p_result = 'lose' THEN 1 ELSE 0 END,
        updated_at = now()
      WHERE member_id = p_member;
    END IF;
  END IF;
  SELECT * INTO g FROM fort_profile WHERE member_id = p_member;
  RETURN g;
END
$function$

CREATE OR REPLACE FUNCTION public.fort_set_skin(p_member uuid, p_skin text)
 RETURNS fort_profile
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  g fort_profile;
BEGIN
  IF p_skin NOT IN ('desk', 'cabinet', 'water', 'plant', 'copier', 'server') THEN RAISE EXCEPTION 'UNKNOWN_SKIN %', p_skin; END IF;
  INSERT INTO fort_profile (member_id) VALUES (p_member) ON CONFLICT (member_id) DO NOTHING;
  SELECT * INTO g FROM fort_profile WHERE member_id = p_member FOR UPDATE;
  IF (p_skin = 'water' AND g.games < 1) OR (p_skin = 'plant' AND g.games < 5)
     OR (p_skin = 'copier' AND g.wins < 3) OR (p_skin = 'server' AND g.wins < 10) THEN
    RAISE EXCEPTION 'LOCKED_SKIN %', p_skin;
  END IF;
  UPDATE fort_profile SET skin = p_skin, updated_at = now() WHERE member_id = p_member RETURNING * INTO g;
  RETURN g;
END
$function$

CREATE OR REPLACE FUNCTION public.members_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF current_user IN ('authenticated', 'anon') THEN
    IF TG_OP = 'INSERT' THEN
      IF NEW.role IS DISTINCT FROM 'member' OR NEW.auth_user_id IS NOT NULL
         OR NEW.can_manage_members OR NEW.left_at IS NOT NULL THEN
        RAISE EXCEPTION 'members: role, auth_user_id, can_manage_members, left_at can only be set by the server' USING ERRCODE = '42501';
      END IF;
    ELSIF NEW.role IS DISTINCT FROM OLD.role
       OR NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id
       OR NEW.can_manage_members IS DISTINCT FROM OLD.can_manage_members
       OR NEW.left_at IS DISTINCT FROM OLD.left_at THEN
      RAISE EXCEPTION 'members: role, auth_user_id, can_manage_members, left_at can only be changed by the server' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.open_baseball_box(p_box uuid, p_member uuid)
 RETURNS baseball_gift_boxes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r baseball_gift_boxes;
  t text;
  pt text;
  dup boolean;
  roll double precision;
BEGIN
  SELECT * INTO r FROM baseball_gift_boxes WHERE id = p_box FOR UPDATE;
  IF NOT FOUND OR r.recipient_id <> p_member THEN RAISE EXCEPTION 'BOX_NOT_FOUND'; END IF;
  IF r.opened_at IS NOT NULL THEN RETURN r; END IF;
  t := COALESCE(r.preset_team, (ARRAY['lg','doosan','kia','samsung','ssg','lotte','hanwha','nc','kt','kiwoom'])[1 + floor(random() * 10)::int]);
  pt := r.preset_part;
  IF pt IS NULL THEN
    roll := random();
    SELECT x.part INTO pt FROM (
      SELECT part, sum(weight) OVER (ORDER BY sort, part) AS cum, sum(weight) OVER () AS total
        FROM baseball_parts_in_season()
    ) x
     WHERE x.cum > roll * x.total
     ORDER BY x.cum
     LIMIT 1;
  END IF;
  IF pt IS NULL THEN pt := 'cap'; END IF;
  dup := EXISTS (SELECT 1 FROM baseball_gear WHERE member_id = p_member AND team = t AND part = pt);
  IF NOT dup THEN
    INSERT INTO baseball_gear (member_id, team, part, box_id) VALUES (p_member, t, pt, p_box);
  END IF;
  UPDATE baseball_gift_boxes
     SET opened_at = now(), item_team = t, item_part = pt, duplicate = dup
   WHERE id = p_box
  RETURNING * INTO r;
  RETURN r;
END
$function$

CREATE OR REPLACE FUNCTION public.paper_tower_claim(p_kind text)
 RETURNS paper_towers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_me uuid := current_member_id();
  v_limit int := 5;
  v_used int;
  t paper_towers;
BEGIN
  IF v_me IS NULL THEN RAISE EXCEPTION 'NOT_MEMBER'; END IF;
  t := paper_tower_current();
  SELECT * INTO t FROM paper_towers WHERE id = t.id FOR UPDATE;
  IF t.lock_by IS NOT NULL AND t.lock_until > now() THEN
    IF t.lock_by = v_me THEN RAISE EXCEPTION 'ALREADY_MINE'; END IF;
    RAISE EXCEPTION 'LOCKED';
  END IF;
  IF t.last_by = v_me THEN RAISE EXCEPTION 'CONSECUTIVE'; END IF;
  SELECT count(*) INTO v_used FROM paper_tower_moves WHERE tower_id = t.id AND member_id = v_me;
  IF v_used >= v_limit THEN RAISE EXCEPTION 'LIMIT'; END IF;
  INSERT INTO paper_tower_moves (tower_id, member_id, floor, kind)
  VALUES (t.id, v_me, (SELECT count(*) + 1 FROM paper_tower_moves WHERE tower_id = t.id), COALESCE(t.next_kind, p_kind));
  UPDATE paper_towers SET lock_by = v_me, lock_until = now() + interval '20 seconds',
    next_kind = COALESCE(next_kind, p_kind), updated_at = now()
  WHERE id = t.id RETURNING * INTO t;
  RETURN t;
END $function$

CREATE OR REPLACE FUNCTION public.paper_tower_commit(p_tower_id bigint, p_version integer, p_state jsonb, p_collapsed boolean, p_next_kind text, p_replay jsonb DEFAULT NULL::jsonb)
 RETURNS paper_towers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_me uuid := current_member_id();
  v_move bigint;
  t paper_towers;
BEGIN
  IF v_me IS NULL THEN RAISE EXCEPTION 'NOT_MEMBER'; END IF;
  SELECT * INTO t FROM paper_towers WHERE id = p_tower_id FOR UPDATE;
  IF NOT FOUND OR t.ended_at IS NOT NULL THEN RAISE EXCEPTION 'TOWER_CLOSED'; END IF;
  IF t.lock_by IS DISTINCT FROM v_me OR t.lock_until < now() - interval '3 seconds' THEN RAISE EXCEPTION 'LOCK_LOST'; END IF;
  IF t.version <> p_version THEN RAISE EXCEPTION 'VERSION'; END IF;
  SELECT id INTO v_move FROM paper_tower_moves WHERE tower_id = t.id AND member_id = v_me AND result IS NULL ORDER BY id DESC LIMIT 1;
  UPDATE paper_tower_moves SET result = CASE WHEN p_collapsed THEN 'collapse' ELSE 'safe' END, replay = p_replay, state_before = t.state WHERE id = v_move;
  IF p_collapsed THEN
    UPDATE paper_towers SET ended_at = now(), end_reason = 'collapse', collapsed_by = v_me,
      lock_by = NULL, lock_until = NULL, last_by = v_me, version = version + 1, updated_at = now()
    WHERE id = t.id;
    INSERT INTO paper_towers (day, next_kind) VALUES ((now() AT TIME ZONE 'Asia/Seoul')::date, p_next_kind);
    SELECT * INTO t FROM paper_towers WHERE ended_at IS NULL;
  ELSE
    UPDATE paper_towers SET state = COALESCE(p_state, '[]'::jsonb), floors = jsonb_array_length(COALESCE(p_state, '[]'::jsonb)),
      next_kind = p_next_kind, last_by = v_me, lock_by = NULL, lock_until = NULL, version = version + 1, updated_at = now()
    WHERE id = t.id RETURNING * INTO t;
  END IF;
  RETURN t;
END $function$

CREATE OR REPLACE FUNCTION public.paper_tower_current()
 RETURNS paper_towers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t paper_towers;
  v_open boolean;
  v_today date := (now() AT TIME ZONE 'Asia/Seoul')::date;
BEGIN
  SELECT * INTO t FROM paper_towers WHERE ended_at IS NULL FOR UPDATE;
  v_open := FOUND;
  IF v_open AND t.day < v_today AND t.floors = 0 AND NOT EXISTS (SELECT 1 FROM paper_tower_moves WHERE tower_id = t.id) THEN
    -- 아무도 안 쌓은 어제 탑은 기록 없이 날짜만 오늘로
    UPDATE paper_towers SET day = v_today, updated_at = now() WHERE id = t.id RETURNING * INTO t;
  ELSIF v_open AND t.day < v_today AND (t.lock_until IS NULL OR t.lock_until < now()) THEN
    UPDATE paper_towers SET ended_at = now(), end_reason = 'complete', lock_by = NULL, lock_until = NULL, updated_at = now() WHERE id = t.id;
    v_open := false;
  END IF;
  IF NOT v_open THEN
    INSERT INTO paper_towers (day) VALUES (v_today) ON CONFLICT DO NOTHING;
    SELECT * INTO t FROM paper_towers WHERE ended_at IS NULL;
  END IF;
  RETURN t;
END $function$

CREATE OR REPLACE FUNCTION public.paper_tower_reset()
 RETURNS paper_towers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t paper_towers;
BEGIN
  IF NOT is_lead() THEN RAISE EXCEPTION 'NOT_LEAD'; END IF;
  UPDATE paper_towers SET ended_at = now(), end_reason = 'reset', collapsed_by = NULL,
    lock_by = NULL, lock_until = NULL, version = version + 1, updated_at = now()
  WHERE ended_at IS NULL;
  INSERT INTO paper_towers (day) VALUES ((now() AT TIME ZONE 'Asia/Seoul')::date);
  SELECT * INTO t FROM paper_towers WHERE ended_at IS NULL;
  RETURN t;
END $function$

CREATE OR REPLACE FUNCTION public.pick_final_menu(p_names text[], p_weights numeric[])
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_date   date := (now() AT TIME ZONE 'Asia/Seoul')::date;
  v_row    day_state%ROWTYPE;
  v_total  numeric := 0;
  v_rand   numeric;
  v_cum    numeric := 0;
  v_picked text;
  i        int;
BEGIN
  IF p_names IS NULL OR array_length(p_names, 1) IS NULL OR array_length(p_names, 1) = 0 THEN
    RETURN NULL;
  END IF;

  INSERT INTO day_state (date) VALUES (v_date) ON CONFLICT (date) DO NOTHING;
  SELECT * INTO v_row FROM day_state WHERE day_state.date = v_date FOR UPDATE;

  IF v_row.final_menu IS NOT NULL AND v_row.final_menu = ANY(p_names) THEN
    RETURN v_row.final_menu;
  END IF;

  FOR i IN 1..array_length(p_names, 1) LOOP
    v_total := v_total + greatest(coalesce(p_weights[i], 0), 0);
  END LOOP;

  IF v_total <= 0 THEN
    v_picked := p_names[1];
  ELSE
    v_rand := random() * v_total;
    FOR i IN 1..array_length(p_names, 1) LOOP
      v_cum := v_cum + greatest(coalesce(p_weights[i], 0), 0);
      IF v_picked IS NULL AND v_rand <= v_cum THEN
        v_picked := p_names[i];
      END IF;
    END LOOP;
  END IF;

  UPDATE day_state SET final_menu = v_picked WHERE day_state.date = v_date;
  RETURN v_picked;
END;
$function$

CREATE OR REPLACE FUNCTION public.race_buy(p_member uuid, p_part text)
 RETURNS race_garage
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  price int := race_part_price(p_part);
  g race_garage;
BEGIN
  IF price <= 0 THEN RAISE EXCEPTION 'UNKNOWN_PART %', p_part; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('race_coins:' || p_member::text));
  INSERT INTO race_garage (member_id) VALUES (p_member) ON CONFLICT (member_id) DO NOTHING;
  SELECT * INTO g FROM race_garage WHERE member_id = p_member FOR UPDATE;
  IF p_part = ANY (g.owned)
     OR EXISTS (SELECT 1 FROM race_gifts WHERE member_id = p_member AND part = p_part AND team IS NULL AND expires_at IS NULL) THEN
    RAISE EXCEPTION 'ALREADY_OWNED';
  END IF;
  IF p_part = 'super' AND NOT race_has(p_member, 'sport', NULL) THEN RAISE EXCEPTION 'NEED_SPORT'; END IF;
  IF g.coins < price THEN RAISE EXCEPTION 'NOT_ENOUGH_COINS %', g.coins; END IF;
  UPDATE race_garage SET
    coins = coins - price,
    owned = array_append(owned, p_part),
    equipped = CASE WHEN p_part IN ('sport', 'super') THEN (equipped - 'bodyTeam') || jsonb_build_object('body', p_part)
                    ELSE equipped || jsonb_build_object(p_part, 'own') END,
    updated_at = now()
  WHERE member_id = p_member
  RETURNING * INTO g;
  RETURN g;
END
$function$

CREATE OR REPLACE FUNCTION public.race_interior_buy(p_member uuid, p_slot text, p_v text, p_team text)
 RETURNS race_garage
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  price int := race_interior_price(p_slot, p_v);
  k text := p_slot || ':' || p_v || ':' || COALESCE(p_team, 'base');
  g race_garage;
BEGIN
  IF race_interior_kind(p_slot, p_v) IS DISTINCT FROM 'shop' OR price <= 0 THEN RAISE EXCEPTION 'NOT_FOR_SALE'; END IF;
  IF NOT race_interior_team_ok(COALESCE(p_team, 'base')) THEN RAISE EXCEPTION 'UNKNOWN_TEAM %', p_team; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('race_coins:' || p_member::text));
  INSERT INTO race_garage (member_id) VALUES (p_member) ON CONFLICT (member_id) DO NOTHING;
  SELECT * INTO g FROM race_garage WHERE member_id = p_member FOR UPDATE;
  IF k = ANY (g.interior_owned) THEN RAISE EXCEPTION 'ALREADY_OWNED'; END IF;
  IF g.coins < price THEN RAISE EXCEPTION 'NOT_ENOUGH_COINS %', g.coins; END IF;
  UPDATE race_garage SET
    coins = coins - price,
    interior_owned = array_append(interior_owned, k),
    interior = interior || jsonb_build_object(p_slot, jsonb_build_object('v', p_v, 'team', p_team)),
    updated_at = now()
  WHERE member_id = p_member RETURNING * INTO g;
  RETURN g;
END
$function$

CREATE OR REPLACE FUNCTION public.race_interior_draw(p_member uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  price int := 10;
  g race_garage;
  k text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('race_coins:' || p_member::text));
  INSERT INTO race_garage (member_id) VALUES (p_member) ON CONFLICT (member_id) DO NOTHING;
  SELECT * INTO g FROM race_garage WHERE member_id = p_member FOR UPDATE;
  IF g.coins < price THEN RAISE EXCEPTION 'NOT_ENOUGH_COINS %', g.coins; END IF;
  SELECT c INTO k FROM (
    SELECT sv.s || ':' || sv.v || ':' || t.team AS c
    FROM (VALUES
      ('wheel','race'),('wheel','bus'),('dash','stitch'),('dash','carbon'),('dash','wood'),
      ('screen','led'),('screen','tv'),('screen','cheer'),('charm','pennant'),('charm','ball'),('charm','star'),
      ('frame','chrome'),('frame','stripe'),('frame','neon'),('frame','gold'),
      ('doll','dog'),('doll','penguin'),('doll','duck'),('hands','mitt'),('hands','mitten')
    ) AS sv(s, v)
    CROSS JOIN (VALUES ('base'),('lg'),('doosan'),('kia'),('samsung'),('ssg'),('lotte'),('hanwha'),('nc'),('kt'),('kiwoom')) AS t(team)
  ) pool
  WHERE NOT (c = ANY (g.interior_owned))
  ORDER BY random() LIMIT 1;
  IF k IS NULL THEN RAISE EXCEPTION 'ALL_OWNED'; END IF;
  UPDATE race_garage SET
    coins = coins - price,
    interior_owned = array_append(interior_owned, k),
    interior_gifts = array_append(interior_gifts, k),
    updated_at = now()
  WHERE member_id = p_member RETURNING * INTO g;
  RETURN jsonb_build_object('garage', to_jsonb(g), 'got', k);
END
$function$

CREATE OR REPLACE FUNCTION public.race_interior_set(p_member uuid, p_interior jsonb)
 RETURNS race_garage
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  g race_garage;
  eq jsonb := '{}'::jsonb;
  s text;
  v text;
  t text;
  kind text;
  seen text[] := '{}';
BEGIN
  INSERT INTO race_garage (member_id) VALUES (p_member) ON CONFLICT (member_id) DO NOTHING;
  SELECT * INTO g FROM race_garage WHERE member_id = p_member FOR UPDATE;
  FOREACH s IN ARRAY ARRAY['wheel', 'dash', 'screen', 'charm', 'frame', 'doll', 'hands'] LOOP
    v := p_interior -> s ->> 'v';
    t := COALESCE(NULLIF(p_interior -> s ->> 'team', ''), 'base');
    IF v IS NULL OR NOT race_interior_team_ok(t) THEN CONTINUE; END IF;
    kind := race_interior_kind(s, v);
    IF kind IS NULL THEN CONTINUE; END IF;
    IF kind = 'free' OR (s || ':' || v || ':' || t) = ANY (g.interior_owned) THEN
      eq := eq || jsonb_build_object(s, jsonb_build_object('v', v, 'team', CASE WHEN t = 'base' THEN NULL ELSE t END));
      seen := array_append(seen, s || ':' || v || ':' || t);
    END IF;
  END LOOP;
  UPDATE race_garage SET
    interior = eq,
    interior_gifts = ARRAY(SELECT x FROM unnest(interior_gifts) x WHERE NOT (x = ANY (seen))),
    updated_at = now()
  WHERE member_id = p_member RETURNING * INTO g;
  RETURN g;
END
$function$

CREATE OR REPLACE FUNCTION public.race_reward(p_member uuid, p_rid text, p_rank integer, p_humans integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  today date := (now() AT TIME ZONE 'Asia/Seoul')::date;
  want int;
  got_today int;
  got_solo int;
  give int;
BEGIN
  IF p_rank <= 0 THEN want := 0;
  ELSIF p_humans <= 1 THEN want := 1;
  ELSIF p_rank = 1 THEN want := 5;
  ELSIF p_rank = 2 THEN want := 3;
  ELSIF p_rank = 3 THEN want := 2;
  ELSE want := 1;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('race_coins:' || p_member::text));
  IF EXISTS (SELECT 1 FROM race_rewards WHERE member_id = p_member AND rid = p_rid) THEN RETURN 0; END IF;
  SELECT COALESCE(sum(coins), 0) INTO got_today FROM race_rewards WHERE member_id = p_member AND day = today;
  SELECT COALESCE(sum(coins), 0) INTO got_solo FROM race_rewards WHERE member_id = p_member AND day = today AND humans <= 1;
  give := LEAST(want, GREATEST(0, 30 - got_today));
  IF p_humans <= 1 THEN give := LEAST(give, GREATEST(0, 5 - got_solo)); END IF;
  INSERT INTO race_rewards (member_id, rid, day, rank, humans, coins) VALUES (p_member, p_rid, today, p_rank, p_humans, give);
  INSERT INTO race_garage (member_id, coins) VALUES (p_member, give)
  ON CONFLICT (member_id) DO UPDATE SET coins = race_garage.coins + give, updated_at = now();
  RETURN give;
END
$function$

CREATE OR REPLACE FUNCTION public.race_set(p_member uuid, p_team text, p_equipped jsonb)
 RETURNS race_garage
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  g race_garage;
  eq jsonb := '{}'::jsonb;
  k text;
  v text;
  body text;
  bt text;
BEGIN
  IF p_team IS NOT NULL AND p_team NOT IN ('lg', 'doosan', 'kia', 'samsung', 'ssg', 'lotte', 'hanwha', 'nc', 'kt', 'kiwoom') THEN
    RAISE EXCEPTION 'UNKNOWN_TEAM %', p_team;
  END IF;
  INSERT INTO race_garage (member_id) VALUES (p_member) ON CONFLICT (member_id) DO NOTHING;
  SELECT * INTO g FROM race_garage WHERE member_id = p_member FOR UPDATE;
  IF p_equipped IS NULL THEN
    eq := g.equipped;
  ELSE
    FOREACH k IN ARRAY ARRAY['flag', 'wheels', 'exhaust', 'wing'] LOOP
      v := p_equipped ->> k;
      IF v IN ('true', 'own') THEN
        IF race_has(p_member, k, NULL) THEN eq := eq || jsonb_build_object(k, 'own'); END IF;
      ELSIF v IS NOT NULL AND v <> 'false' THEN
        IF race_has(p_member, k, v) THEN eq := eq || jsonb_build_object(k, v); END IF;
      END IF;
    END LOOP;
    body := p_equipped ->> 'body';
    bt := NULLIF(p_equipped ->> 'bodyTeam', '');
    IF body IN ('sport', 'super') AND race_has(p_member, body, bt) THEN
      eq := eq || jsonb_build_object('body', body) || CASE WHEN bt IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('bodyTeam', bt) END;
    END IF;
  END IF;
  UPDATE race_garage SET team = COALESCE(p_team, team), equipped = eq, updated_at = now()
  WHERE member_id = p_member RETURNING * INTO g;
  RETURN g;
END
$function$

CREATE OR REPLACE FUNCTION public.roulette_weights(p_menu text)
 RETURNS TABLE(member_id uuid, label text, weight numeric)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_lead_total   numeric;
  v_part_total   numeric;
  v_member_total numeric;
  v_corp         numeric;
  v_lead_n       int;
  v_part_n       int;
  v_member_n     int;
  v_n            int;
  v_vacant       numeric := 0;
  v_extra        numeric;
BEGIN
  IF p_menu = 'meal' THEN
    v_lead_total := 40; v_part_total := 20; v_member_total := 20; v_corp := 20;
  ELSIF p_menu = 'coffee' THEN
    v_lead_total := 30; v_part_total := 20; v_member_total := 30; v_corp := 20;
  ELSIF p_menu = 'snack' THEN
    v_lead_total := 0;  v_part_total := 0;  v_member_total := 100; v_corp := 0;
  ELSE
    RAISE EXCEPTION 'invalid menu: %', p_menu;
  END IF;

  SELECT count(*) INTO v_n FROM members;
  IF v_n = 0 THEN
    RETURN;
  END IF;

  IF p_menu = 'snack' THEN
    RETURN QUERY
      SELECT m.id, m.name, (v_member_total / v_n)::numeric
      FROM members m;
    RETURN;
  END IF;

  SELECT count(*) INTO v_lead_n   FROM members WHERE role = 'lead';
  SELECT count(*) INTO v_part_n   FROM members WHERE role = 'part_lead';
  SELECT count(*) INTO v_member_n FROM members WHERE role = 'member';

  IF v_lead_n = 0   THEN v_vacant := v_vacant + v_lead_total;   END IF;
  IF v_part_n = 0   THEN v_vacant := v_vacant + v_part_total;   END IF;
  IF v_member_n = 0 THEN v_vacant := v_vacant + v_member_total; END IF;
  v_extra := v_vacant / v_n;

  RETURN QUERY
    SELECT
      m.id,
      m.name,
      (
        CASE m.role
          WHEN 'lead'      THEN CASE WHEN v_lead_n = 0   THEN 0 ELSE v_lead_total / v_lead_n     END
          WHEN 'part_lead' THEN CASE WHEN v_part_n = 0   THEN 0 ELSE v_part_total / v_part_n     END
          ELSE                  CASE WHEN v_member_n = 0 THEN 0 ELSE v_member_total / v_member_n END
        END + v_extra
      )::numeric AS weight
    FROM members m;

  IF v_corp > 0 THEN
    RETURN QUERY SELECT NULL::uuid, '법인카드'::text, v_corp::numeric;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_meeting_progress(p_meeting_id uuid, p_member_id uuid, p_content text, p_expected_version integer, p_updated_by text, p_kind text DEFAULT 'note'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  r team_log_meeting_progress;
BEGIN
  IF p_expected_version = 0 THEN
    INSERT INTO team_log_meeting_progress (meeting_id, member_id, kind, content, version, updated_at, updated_by)
    VALUES (p_meeting_id, p_member_id, p_kind, p_content, 1, now(), p_updated_by)
    ON CONFLICT (meeting_id, member_id, kind) DO NOTHING
    RETURNING * INTO r;
  ELSE
    UPDATE team_log_meeting_progress
       SET content = p_content,
           version = version + 1,
           updated_at = now(),
           updated_by = p_updated_by
     WHERE meeting_id = p_meeting_id AND member_id = p_member_id AND kind = p_kind AND version = p_expected_version
    RETURNING * INTO r;
  END IF;
  IF NOT FOUND THEN
    SELECT * INTO r FROM team_log_meeting_progress WHERE meeting_id = p_meeting_id AND member_id = p_member_id AND kind = p_kind;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('status', 'not_found');
    END IF;
    RETURN jsonb_build_object('status', 'conflict', 'row', to_jsonb(r));
  END IF;
  RETURN jsonb_build_object('status', 'ok', 'row', to_jsonb(r));
END
$function$

CREATE OR REPLACE FUNCTION public.save_report_update(p_item_id uuid, p_meeting_id uuid, p_field text, p_content text, p_expected_version integer, p_updated_by text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  r team_log_report_updates;
BEGIN
  IF p_field NOT IN ('update', 'feedback') THEN
    RAISE EXCEPTION 'invalid field %', p_field;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM team_log_report_items WHERE id = p_item_id)
     OR NOT EXISTS (SELECT 1 FROM team_log_meetings WHERE id = p_meeting_id) THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;

  INSERT INTO team_log_report_updates (item_id, meeting_id)
  VALUES (p_item_id, p_meeting_id)
  ON CONFLICT (item_id, meeting_id) DO NOTHING;

  IF p_field = 'update' THEN
    UPDATE team_log_report_updates
       SET update_text = p_content, update_version = update_version + 1, updated_at = now(), updated_by = p_updated_by
     WHERE item_id = p_item_id AND meeting_id = p_meeting_id AND update_version = p_expected_version
    RETURNING * INTO r;
  ELSE
    UPDATE team_log_report_updates
       SET feedback = p_content, feedback_version = feedback_version + 1, updated_at = now(), updated_by = p_updated_by
     WHERE item_id = p_item_id AND meeting_id = p_meeting_id AND feedback_version = p_expected_version
    RETURNING * INTO r;
  END IF;

  IF NOT FOUND THEN
    SELECT * INTO r FROM team_log_report_updates WHERE item_id = p_item_id AND meeting_id = p_meeting_id;
    RETURN jsonb_build_object('status', 'conflict', 'row', to_jsonb(r));
  END IF;
  RETURN jsonb_build_object('status', 'ok', 'row', to_jsonb(r));
END
$function$

CREATE OR REPLACE FUNCTION public.send_baseball_box(p_sender uuid, p_recipient uuid, p_message text)
 RETURNS baseball_gift_boxes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  bal int;
  r baseball_gift_boxes;
BEGIN
  IF p_sender = p_recipient THEN RAISE EXCEPTION 'SELF_GIFT'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('baseball_credit:' || p_sender::text));
  bal := baseball_credit_balance(p_sender);
  IF bal < 10 THEN RAISE EXCEPTION 'NOT_ENOUGH_CREDIT %', bal; END IF;
  INSERT INTO baseball_gift_boxes (kind, sender_id, recipient_id, cost, message)
  VALUES ('credit', p_sender, p_recipient, 10, NULLIF(btrim(COALESCE(p_message, '')), ''))
  RETURNING * INTO r;
  RETURN r;
END
$function$

CREATE OR REPLACE FUNCTION public.send_baseball_ticket_box(p_sender uuid, p_recipient uuid, p_message text)
 RETURNS baseball_gift_boxes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t baseball_gift_tickets;
  r baseball_gift_boxes;
BEGIN
  IF p_sender = p_recipient THEN RAISE EXCEPTION 'SELF_GIFT'; END IF;
  SELECT * INTO t FROM baseball_gift_tickets
   WHERE owner_id = p_sender AND used_at IS NULL
   ORDER BY created_at
   LIMIT 1
   FOR UPDATE SKIP LOCKED;
